def validate_all(record):
    """Check name, age and email. Report EVERY problem, not just the first."""
    errors = []
    if not isinstance(record.get("name"), str) or not record["name"]:
        errors.append(ValueError("name is required"))
    # TODO: age must be an int (TypeError("age must be an int")),
    #       and if it is an int it must be >= 0 (ValueError("age must be >= 0"))
    # TODO: email must contain "@" (ValueError("email must contain @"))
    # TODO: if errors is not empty, raise ExceptionGroup("invalid record", errors)

try:
    validate_all({"name": "", "age": -3, "email": "x"})
except ExceptionGroup as eg:
    print(eg.message, len(eg.exceptions))
    for e in eg.exceptions:
        print(type(e).__name__, e)

practice_challenges.test_code:
ok = {"name": "Asha", "age": 30, "email": "a@b.co"}
assert validate_all(ok) is None, "a valid record should not raise"

try:
    validate_all({"name": "", "age": -3, "email": "x"})
    raise AssertionError("an invalid record must raise")
except ExceptionGroup as eg:
    assert eg.message == "invalid record"
    assert [type(e) for e in eg.exceptions] == [ValueError, ValueError, ValueError]
    assert [str(e) for e in eg.exceptions] == ["name is required", "age must be >= 0", "email must contain @"]

try:
    validate_all({"name": "Ravi", "age": "ten", "email": "r@x.io"})
    raise AssertionError("a bad age type must raise")
except ExceptionGroup as eg:
    assert len(eg.exceptions) == 1 and isinstance(eg.exceptions[0], TypeError)

try:
    validate_all({"name": "Ravi", "age": 5, "email": "nope"})
    raise AssertionError("a bad email must raise")
except ExceptionGroup as eg:
    assert [str(e) for e in eg.exceptions] == ["email must contain @"]

assert count_by_type(ExceptionGroup("m", [ValueError("a"), ValueError("b"), TypeError("c")])) == {"ValueError": 2, "TypeError": 1}
assert count_by_type(ExceptionGroup("m", [TypeError("c")])) == {"ValueError": 0, "TypeError": 1}
assert count_by_type(ExceptionGroup("m", [ValueError("a"), ValueError("b"), ValueError("c")])) == {"ValueError": 3, "TypeError": 0}
import inspect
assert "except*" in inspect.getsource(count_by_type), "use except* clauses, not isinstance checks"

