def fetch(name):
    if name == "bad-url":
        raise ConnectionError("cannot reach " + name)
    if name == "bad-json":
        raise ValueError("not valid JSON: " + name)
    return name.upper()

errors = []
for name in ["alpha", "bad-url", "beta", "bad-json"]:
    try:
        print("ok", fetch(name))
    except Exception as exc:
        errors.append(exc)

try:
    if errors:
        raise ExceptionGroup("fetch failed", errors)
except* ConnectionError as g:
    print("network problems:", [str(e) for e in g.exceptions])
except* ValueError as g:
    print("data problems:", [str(e) for e in g.exceptions])
